package main

import "fmt"

// 1. Definisi Interface
type PaymentGateway interface {
	Pay(amount float64) string
}

// 2. Struct Stripe (Tipe Konkret 1)
type Stripe struct{}

// Stripe otomatis mengimplementasikan PaymentGateway karena memiliki fungsi Pay()
func (s Stripe) Pay(amount float64) string {
	return fmt.Sprintf("Membayar $%.2f via Stripe", amount)
}

// 3. Struct Midtrans (Tipe Konkret 2)
type Midtrans struct{}

func (m Midtrans) Pay(amount float64) string {
	return fmt.Sprintf("Membayar Rp%.2f via Midtrans", amount)
}

// 4. Fungsi yang menerima Interface
// Ini membuat kode kita fleksibel (Bisa menerima Stripe maupun Midtrans)
func checkout(gateway PaymentGateway, amount float64) {
	result := gateway.Pay(amount)
	fmt.Println("Proses:", result)
}

func main() {
	fmt.Println("=== Interface Action ===")
	stripe := Stripe{}
	midtrans := Midtrans{}

	// Kita bisa mengirim struct apapun asalkan punya method Pay()
	checkout(stripe, 15.50)
	checkout(midtrans, 150000.0)

	fmt.Println("\n=== Empty Interface (any) ===")
	cetakApaSaja("Halo!")
	cetakApaSaja(404)
	cetakApaSaja(true)
}

// Menerima tipe data apa pun (any = interface{})
func cetakApaSaja(data any) {
	fmt.Printf("Data: %v, Tipe: %T\n", data, data)
}
